/// Example 4 of `apply-delta`.
#[test]
fn apply_delta_example_4() {
    let tenant: Option<types::TenantState> = fixture_fx_option_tenant_state_1();
    let delta: types::StateDelta = types::StateDelta {
        tenant: types::TenantId("alpha".to_string()),
        base_revision: Some(types::StateRevision(4)),
        new_revision: types::StateRevision(6),
        next_record: 1,
        event_seq: 6,
        ops: vec![types::DeltaOp::PutMember {
            principal: types::PrincipalId("alpha:writer1".to_string()),
            roles: std::collections::BTreeSet::new(),
        }],
    };
    assert_eq!(
        apply_delta(&tenant, &delta),
        Err(types::Rejection::Rejected(types::DomainError {
            kind: types::ErrorKind::VersionConflict,
            message: "delta is based on Some(StateRevision(4)), state is at Some(StateRevision(5))"
                .to_string(),
            evidence: Vec::new(),
            missing: None
        }))
    );
}

