/// Example 1 of `mutation-reply-of`.
#[test]
fn mutation_reply_of_example_1() {
    let t: types::TransitionResult = types::TransitionResult {
        delta: types::StateDelta {
            tenant: types::TenantId("alpha".to_string()),
            base_revision: Some(types::StateRevision(5)),
            new_revision: types::StateRevision(6),
            next_record: 6,
            event_seq: 6,
            ops: Vec::new(),
        },
        events: Vec::new(),
        effects: Vec::new(),
        evidence: vec![
            types::Check {
                rule: "policy:builtin_owner".to_string(),
                passed: true,
                detail: "x".to_string(),
            },
            types::Check {
                rule: "record:valid".to_string(),
                passed: true,
                detail: "y".to_string(),
            },
        ],
        output: types::Output::Record {
            object: types::ObjectTypeId("post".to_string()),
            id: types::RecordId(5),
            version: 1,
        },
    };
    let want_: Option<types::MutationReply> = Some(types::MutationReply {
        object: "post".to_string(),
        id: 5,
        version: Some(1),
        revision: 6,
        event_seq: 6,
        checks_passed: 2,
    });
    assert_eq!(mutation_reply_of(&t), Ok(want_));
}

