/// A writer without a policy cannot read the draft, so the refusal says it is not there.
#[test]
fn unreadable_as_missing_example_1() {
    let d: types::DomainError = types::DomainError {
        kind: types::ErrorKind::Unauthorized,
        message: "m".to_string(),
        evidence: Vec::new(),
        missing: None,
    };
    let tenant: types::TenantState = fixture_fx_tenant_state_13();
    let coverage: types::Coverage = types::Coverage::Complete;
    let object: types::ObjectTypeId = types::ObjectTypeId("post".to_string());
    let id: types::RecordId = types::RecordId(3);
    let context: types::Context = types::Context {
        tenant: types::TenantId("alpha".to_string()),
        principal: types::Principal::User(types::PrincipalId("alpha:writer".to_string())),
        session: Some(types::SessionId("s-2".to_string())),
        now: crate::prelude::Timestamp(3000),
        correlation: "c-1".to_string(),
        verified_address: None,
        idempotency_key: None,
        language: None,
        hop: None,
    };
    let want_: types::DomainError = types::DomainError {
        kind: types::ErrorKind::UnknownRecord,
        message: "no post 3".to_string(),
        evidence: vec![types::Check {
            rule: "intent:unknown_record".to_string(),
            passed: false,
            detail: "no post 3".to_string(),
        }],
        missing: None,
    };
    assert_eq!(
        unreadable_as_missing(&d, &tenant, &coverage, &object, &id, &context),
        Ok(want_)
    );
}

