/// Example 2 of `team-role`.
#[test]
fn team_role_example_2() {
    let d: types::Draft = fixture_fx_draft_17();
    let team: types::TeamId = types::TeamId("desk".to_string());
    let role: types::RoleId = types::RoleId("nobody".to_string());
    let grant: bool = true;
    assert_eq!(
        team_role(&d, &team, &role, grant),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::UnknownRole,
                message: "no role nobody".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:builtin_owner".to_string(),
                        passed: true,
                        detail: "Manage on Members".to_string()
                    },
                    types::Check {
                        rule: "intent:unknown_role".to_string(),
                        passed: false,
                        detail: "no role nobody".to_string()
                    }
                ],
                missing: None
            }
        )))
    );
}

/// A revocation that leaves the tenant no owner is refused, counting the owners through teams: the only owner is a member of the desk team, which holds owner.
#[test]
fn team_role_example_3() {
    let d: types::Draft = fixture_fx_draft_19();
    let team: types::TeamId = types::TeamId("desk".to_string());
    let role: types::RoleId = types::RoleId("owner".to_string());
    let grant: bool = false;
    assert_eq!(
        team_role(&d, &team, &role, grant),
        Err(Failure::Error(types::Rejection::Rejected(
            types::DomainError {
                kind: types::ErrorKind::InvalidIntent,
                message: "a tenant keeps at least one owner".to_string(),
                evidence: vec![
                    types::Check {
                        rule: "policy:builtin_owner".to_string(),
                        passed: true,
                        detail: "Manage on Members".to_string()
                    },
                    types::Check {
                        rule: "permission:confer:owner".to_string(),
                        passed: true,
                        detail: "an owner confers owner".to_string()
                    },
                    types::Check {
                        rule: "intent:invalid_intent".to_string(),
                        passed: false,
                        detail: "a tenant keeps at least one owner".to_string()
                    }
                ],
                missing: None
            }
        )))
    );
}

