/// A scan: the owner reads the last title first, one row, and a cursor for the rest.
#[test]
fn named_read_example_1() {
    let t: types::TenantState = fixture_fx_tenant_state_13();
    let coverage: types::Coverage = types::Coverage::Complete;
    let context: types::Context = types::Context {
        tenant: types::TenantId("alpha".to_string()),
        principal: types::Principal::User(types::PrincipalId("alpha:owner".to_string())),
        session: Some(types::SessionId("s-1".to_string())),
        now: crate::prelude::Timestamp(3000),
        correlation: "c-1".to_string(),
        verified_address: None,
        idempotency_key: None,
        language: None,
        hop: None,
    };
    let query: types::QueryId = types::QueryId("newest".to_string());
    let params: std::collections::BTreeMap<String, types::Value> =
        std::collections::BTreeMap::new();
    let page_size: Option<u32> = None;
    let cursor: Option<types::PageCursor> = None;
    let want_: types::ReadResult = types::ReadResult {
        rows: vec![std::sync::Arc::new(types::Record {
            id: types::RecordId(4),
            object: types::ObjectTypeId("post".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:owner".to_string())),
            created_at: crate::prelude::Timestamp(2002),
            updated_at: crate::prelude::Timestamp(2002),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("published".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("C".to_string()),
                ),
            ]),
        })],
        revision: types::StateRevision(5),
        schema_version: types::SchemaVersion(2),
        next: Some(types::PageCursor::Offset(1)),
    };
    assert_eq!(
        named_read(&t, &coverage, &context, &query, &params, page_size, &cursor),
        Ok(want_)
    );
}

