fn unique_step_example_6() {
    let tenant: types::TenantState = fixture_fx_tenant_state_21();
    let coverage: types::Coverage = types::Coverage::Complete;
    let object: types::ObjectTypeDef = fixture_fx_object_type_def_4();
    let candidate: types::Record = types::Record {
        id: types::RecordId(3),
        object: types::ObjectTypeId("note".to_string()),
        version: 1,
        created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
        created_at: crate::prelude::Timestamp(5000),
        updated_at: crate::prelude::Timestamp(5000),
        fields: std::collections::BTreeMap::from([
            (
                types::FieldId("status".to_string()),
                types::Value::Str("draft".to_string()),
            ),
            (
                types::FieldId("title".to_string()),
                types::Value::Str("First".to_string()),
            ),
        ]),
    };
    let principal: types::Principal = types::Principal::Anonymous;
    let now: crate::prelude::Timestamp = crate::prelude::Timestamp(5000);
    let acc: types::ValidationOutcome = types::ValidationOutcome {
        passed: Vec::new(),
        failed: Vec::new(),
    };
    let u: types::UniqueDef = types::UniqueDef {
        id: types::ConstraintId("title_status".to_string()),
        fields: vec![
            types::FieldId("title".to_string()),
            types::FieldId("status".to_string()),
        ],
        message: "One note per title and status.".to_string(),
    };
    let want_: types::ValidationOutcome = types::ValidationOutcome {
        passed: Vec::new(),
        failed: vec![types::ValidationFailure {
            check: types::Check {
                rule: "unique:note.title_status".to_string(),
                passed: false,
                detail: "One note per title and status.: another record already has these values"
                    .to_string(),
            },
            kind: types::ErrorKind::UniqueViolated,
        }],
    };
    assert_eq!(
        unique_step(&tenant, &coverage, &object, &candidate, &principal, now, &acc, &u),
        Ok(want_)
    );
}

/// Example 1 of `duplicate-check`.
#[test]
fn duplicate_check_example_1() {
    let records: Vec<types::Record> = vec![
        types::Record {
            id: types::RecordId(1),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("draft".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        },
        types::Record {
            id: types::RecordId(2),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("draft".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("First".to_string()),
                ),
            ]),
        },
        types::Record {
            id: types::RecordId(3),
            object: types::ObjectTypeId("note".to_string()),
            version: 1,
            created_by: Some(types::PrincipalId("alpha:writer1".to_string())),
            created_at: crate::prelude::Timestamp(5000),
            updated_at: crate::prelude::Timestamp(5000),
            fields: std::collections::BTreeMap::from([
                (
                    types::FieldId("status".to_string()),
                    types::Value::Str("draft".to_string()),
                ),
                (
                    types::FieldId("title".to_string()),
                    types::Value::Str("Second".to_string()),
                ),
            ]),
        },
    ];
    let object: types::ObjectTypeId = types::ObjectTypeId("note".to_string());
    let u: types::UniqueDef = types::UniqueDef {
        id: types::ConstraintId("title_status".to_string()),
        fields: vec![
            types::FieldId("title".to_string()),
            types::FieldId("status".to_string()),
        ],
        message: "One note per title and status.".to_string(),
    };
    let want_: Vec<types::Check> = vec![types::Check {
        rule: "unique:note.title_status".to_string(),
        passed: false,
        detail: "records 1 and 2 have the same values in title, status".to_string(),
    }];
    assert_eq!(duplicate_check(&records, &object, &u), want_);
}

