/// Two records already share the values (CMS-1556).
#[test]
fn unique_duplicates_example_1() {
    let tenant: types::TenantState = fixture_fx_tenant_state_11();
    let coverage: types::Coverage = types::Coverage::Complete;
    let current: types::TenantSchema = fixture_fx_tenant_schema_21();
    let schema: types::TenantSchema = fixture_fx_tenant_schema_22();
    let changes: Vec<types::SchemaChange> = vec![types::SchemaChange::DefineUnique {
        object: types::ObjectTypeId("note".to_string()),
        unique: types::UniqueDef {
            id: types::ConstraintId("title_status".to_string()),
            fields: vec![
                types::FieldId("title".to_string()),
                types::FieldId("status".to_string()),
            ],
            message: "One note per title and status.".to_string(),
        },
    }];
    let want_: Vec<types::Check> = vec![types::Check {
        rule: "unique:note.title_status".to_string(),
        passed: false,
        detail: "records 1 and 2 have the same values in title, status".to_string(),
    }];
    assert_eq!(
        unique_duplicates(&tenant, &coverage, &current, &schema, &changes),
        Ok(want_)
    );
}

